#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <unistd.h>
#include <pthread.h>
#if defined(__AVX2__) && defined(__FMA__)
#include <immintrin.h>
#define HAVE_AVX2 1
#endif

#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NC 1024
#define MAXT 256

/* Packed buffers are allocated once and reused across calls. */
static float *bufA[MAXT], *bufB[MAXT];
static int g_nthreads = 0;

static int count_physical_cores(void)
{
    long ncpu = sysconf(_SC_NPROCESSORS_ONLN);
    if (ncpu < 1) ncpu = 1;
    int phys = 0;
    for (long i = 0; i < ncpu; i++) {
        char path[128];
        snprintf(path, sizeof path,
                 "/sys/devices/system/cpu/cpu%ld/topology/thread_siblings_list", i);
        FILE *f = fopen(path, "r");
        if (!f) return (int)ncpu;
        int first = -1;
        if (fscanf(f, "%d", &first) != 1) first = -1;
        fclose(f);
        if (first < 0) return (int)ncpu;
        if (first == i) phys++;
    }
    if (phys < 1) phys = (int)ncpu;
    if (phys > MAXT) phys = MAXT;
    return phys;
}

#ifdef HAVE_AVX2
static void kernel(int kc, const float *a, const float *b, float *c, int ldc, int first)
{
    __m256 c00 = _mm256_setzero_ps(), c01 = _mm256_setzero_ps();
    __m256 c10 = _mm256_setzero_ps(), c11 = _mm256_setzero_ps();
    __m256 c20 = _mm256_setzero_ps(), c21 = _mm256_setzero_ps();
    __m256 c30 = _mm256_setzero_ps(), c31 = _mm256_setzero_ps();
    __m256 c40 = _mm256_setzero_ps(), c41 = _mm256_setzero_ps();
    __m256 c50 = _mm256_setzero_ps(), c51 = _mm256_setzero_ps();
    for (int k = 0; k < kc; k++) {
        __m256 b0 = _mm256_load_ps(b);
        __m256 b1 = _mm256_load_ps(b + 8);
        __m256 av;
        av = _mm256_broadcast_ss(a + 0);
        c00 = _mm256_fmadd_ps(av, b0, c00); c01 = _mm256_fmadd_ps(av, b1, c01);
        av = _mm256_broadcast_ss(a + 1);
        c10 = _mm256_fmadd_ps(av, b0, c10); c11 = _mm256_fmadd_ps(av, b1, c11);
        av = _mm256_broadcast_ss(a + 2);
        c20 = _mm256_fmadd_ps(av, b0, c20); c21 = _mm256_fmadd_ps(av, b1, c21);
        av = _mm256_broadcast_ss(a + 3);
        c30 = _mm256_fmadd_ps(av, b0, c30); c31 = _mm256_fmadd_ps(av, b1, c31);
        av = _mm256_broadcast_ss(a + 4);
        c40 = _mm256_fmadd_ps(av, b0, c40); c41 = _mm256_fmadd_ps(av, b1, c41);
        av = _mm256_broadcast_ss(a + 5);
        c50 = _mm256_fmadd_ps(av, b0, c50); c51 = _mm256_fmadd_ps(av, b1, c51);
        a += MR;
        b += NR;
    }
#define ST(r, v0, v1) do { float *p = c + (r) * ldc; \
        if (first) { _mm256_storeu_ps(p, v0); _mm256_storeu_ps(p + 8, v1); } \
        else { _mm256_storeu_ps(p, _mm256_add_ps(_mm256_loadu_ps(p), v0)); \
               _mm256_storeu_ps(p + 8, _mm256_add_ps(_mm256_loadu_ps(p + 8), v1)); } } while (0)
    ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
    ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
}
#else
static void kernel(int kc, const float *a, const float *b, float *c, int ldc, int first)
{
    float acc[MR][NR];
    memset(acc, 0, sizeof acc);
    for (int k = 0; k < kc; k++) {
        for (int r = 0; r < MR; r++) {
            float av = a[r];
            for (int j = 0; j < NR; j++) acc[r][j] += av * b[j];
        }
        a += MR;
        b += NR;
    }
    for (int r = 0; r < MR; r++)
        for (int j = 0; j < NR; j++)
            c[r * ldc + j] = first ? acc[r][j] : c[r * ldc + j] + acc[r][j];
}
#endif

static void pack_B(const float *B, float *Bp, int n, int pc, int kc, int jc, int nc)
{
    for (int j0 = 0; j0 < nc; j0 += NR) {
        int nb = nc - j0 < NR ? nc - j0 : NR;
        float *dst = Bp + (size_t)(j0 / NR) * kc * NR;
        const float *src = B + (size_t)pc * n + jc + j0;
        if (nb == NR) {
            for (int k = 0; k < kc; k++) {
                memcpy(dst, src, NR * sizeof(float));
                dst += NR;
                src += n;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int j = 0;
                for (; j < nb; j++) dst[j] = src[j];
                for (; j < NR; j++) dst[j] = 0.0f;
                dst += NR;
                src += n;
            }
        }
    }
}

static void pack_A(const float *A, float *Ap, int n, int ic, int mc, int pc, int kc)
{
    for (int i0 = 0; i0 < mc; i0 += MR) {
        int mb = mc - i0 < MR ? mc - i0 : MR;
        float *dst = Ap + (size_t)(i0 / MR) * kc * MR;
        const float *src = A + (size_t)(ic + i0) * n + pc;
        if (mb == MR) {
            const float *s0 = src, *s1 = src + n, *s2 = src + 2 * (size_t)n;
            const float *s3 = src + 3 * (size_t)n, *s4 = src + 4 * (size_t)n, *s5 = src + 5 * (size_t)n;
            for (int k = 0; k < kc; k++) {
                dst[0] = s0[k]; dst[1] = s1[k]; dst[2] = s2[k];
                dst[3] = s3[k]; dst[4] = s4[k]; dst[5] = s5[k];
                dst += MR;
            }
        } else {
            for (int k = 0; k < kc; k++) {
                int r = 0;
                for (; r < mb; r++) dst[r] = src[(size_t)r * n + k];
                for (; r < MR; r++) dst[r] = 0.0f;
                dst += MR;
            }
        }
    }
}

typedef struct {
    const float *A, *B;
    float *C;
    int n, r0, r1, tid;
} job_t;

static void do_rows(const float *A, const float *B, float *C, int n, int r0, int r1, int tid)
{
    float *Ap = bufA[tid], *Bp = bufB[tid];
    float tmp[MR * NR] __attribute__((aligned(32)));
    for (int jc = 0; jc < n; jc += NC) {
        int nc = n - jc < NC ? n - jc : NC;
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);
            pack_B(B, Bp, n, pc, kc, jc, nc);
            for (int ic = r0; ic < r1; ic += MC) {
                int mc = r1 - ic < MC ? r1 - ic : MC;
                pack_A(A, Ap, n, ic, mc, pc, kc);
                for (int jr = 0; jr < nc; jr += NR) {
                    int nb = nc - jr < NR ? nc - jr : NR;
                    const float *bp = Bp + (size_t)(jr / NR) * kc * NR;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mb = mc - ir < MR ? mc - ir : MR;
                        const float *ap = Ap + (size_t)(ir / MR) * kc * MR;
                        float *cp = C + (size_t)(ic + ir) * n + jc + jr;
                        if (mb == MR && nb == NR) {
                            kernel(kc, ap, bp, cp, n, first);
                        } else {
                            kernel(kc, ap, bp, tmp, NR, 1);
                            for (int r = 0; r < mb; r++)
                                for (int j = 0; j < nb; j++)
                                    cp[(size_t)r * n + j] = first ? tmp[r * NR + j]
                                                                  : cp[(size_t)r * n + j] + tmp[r * NR + j];
                        }
                    }
                }
            }
        }
    }
}

static void *worker(void *arg)
{
    job_t *j = (job_t *)arg;
    do_rows(j->A, j->B, j->C, j->n, j->r0, j->r1, j->tid);
    return NULL;
}

static int ensure_buffers(int nt)
{
    for (int t = 0; t < nt; t++) {
        if (!bufA[t]) bufA[t] = aligned_alloc(64, (size_t)MC * KC * sizeof(float));
        if (!bufB[t]) bufB[t] = aligned_alloc(64, (size_t)KC * NC * sizeof(float));
        if (!bufA[t] || !bufB[t]) return t;
    }
    return nt;
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    if (!g_nthreads) g_nthreads = count_physical_cores();

    int nt = g_nthreads;
    int strips = (n + MR - 1) / MR;
    if ((long long)n * n * n < 64LL * 64 * 64) nt = 1;
    if (nt > strips) nt = strips;
    if (nt < 1) nt = 1;
    nt = ensure_buffers(nt);
    if (nt < 1) {
        /* allocation failed: naive fallback */
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                float s = 0.0f;
                for (int k = 0; k < n; k++) s += A[(size_t)i * n + k] * B[(size_t)k * n + j];
                C[(size_t)i * n + j] = s;
            }
        return;
    }

    int per = (strips + nt - 1) / nt * MR;
    job_t jobs[MAXT];
    pthread_t th[MAXT];
    int created[MAXT];
    int used = 0;
    for (int t = 0; t < nt; t++) {
        int r0 = t * per, r1 = r0 + per;
        if (r0 >= n) break;
        if (r1 > n) r1 = n;
        jobs[t] = (job_t){A, B, C, n, r0, r1, t};
        used = t + 1;
    }
    for (int t = 1; t < used; t++)
        created[t] = pthread_create(&th[t], NULL, worker, &jobs[t]) == 0;
    do_rows(A, B, C, n, jobs[0].r0, jobs[0].r1, 0);
    for (int t = 1; t < used; t++) {
        if (created[t]) pthread_join(th[t], NULL);
        else do_rows(A, B, C, n, jobs[t].r0, jobs[t].r1, t);
    }
}
